package com.fitpulse.model.entity;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="user_meal_plans") public class UserMealPlan { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Enumerated(EnumType.STRING) @Column(length=30) private com.fitpulse.model.enums.FitnessGoal goal; public com.fitpulse.model.enums.FitnessGoal getGoal(){return goal;} public void setGoal(com.fitpulse.model.enums.FitnessGoal v){goal=v;} @Lob @Column(columnDefinition="LONGTEXT") private String weeklyMenu; public String getWeeklyMenu(){return weeklyMenu;} public void setWeeklyMenu(String v){weeklyMenu=v;} @ManyToOne(optional=false) private User user; @ManyToOne @JoinColumn(name="source_template_id") private MealPlanTemplate sourceTemplate; @Column(nullable=false,length=150) private String name; @Lob @Column(nullable=false,columnDefinition="LONGTEXT") private String meals; @Column(nullable=false,length=3000) private String exampleFoods=""; @Column(nullable=false) private LocalDateTime createdAt; @PrePersist void create(){createdAt=LocalDateTime.now();} public Long getId(){return id;} public User getUser(){return user;} public void setUser(User v){user=v;} public MealPlanTemplate getSourceTemplate(){return sourceTemplate;} public void setSourceTemplate(MealPlanTemplate v){sourceTemplate=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getMeals(){return meals;} public void setMeals(String v){meals=v;} public String getExampleFoods(){return exampleFoods;} public void setExampleFoods(String v){exampleFoods=v;} }
